{"code": "import pandas as pd, numpy as np, statsmodels.formula.api as smf
df = pd.read_csv('data/explore.csv')
for c in ['cool_rate','grain_size','porosity','carbon_pct','nickel_pct']:
    print("===",c)
    for lab in sorted(df['lab'].unique()):
        dd = df[(df['lab']==lab)].dropna(subset=[c,'tensile_mpa'])
        m = smf.ols(f'tensile_mpa ~ {c}', data=dd).fit()
        print(f"  {lab}: coef={m.params[c]:+.3f} p={m.pvalues[c]:.3f} n={int(m.nobs)}")
"}
